R_SFSupportUp1(CLK := g_bSenFeng_SupUp1);
R_SFSupportDown1(CLK := g_bSenFeng_SupDown1);
IF R_SFSupportUp1.Q THEN
  g_bSenFeng_SupUp1 := FALSE;
  IF g_bSenF_SupportIsAvoid1 THEN(*开启Y轴避让检查功能，将对上升命令进行屏蔽*)
    IF g_biAxIsYisHome THEN(*已回零，大于Y避让坐标，不能起来*)
      IF g_fSup2Cy1InYCoor1-g_fCurrentCoordYBuffer>=g_fSup2CylDownDis1 THEN
        IF g_fSenFeng_SupCylType1=0.0 THEN(*上升类型  0支撑上升   1支撑上升并夹中*)
          g_noSupCentringSwitch1 := 30;
        ELSE
          g_noSupCentringSwitch1 := 10;
        END_IF;
        g_boSenFeng_SupUpDone1 := FALSE;
        g_boSenFeng_SupDownDone1 := FALSE; 

      ELSE
        g_noSupCentringSwitch1 := 0;
        g_boSenFeng_SupUpDone1 := TRUE;
        g_boSenFeng_SupDownDone1 := FALSE; 
        M.ENABLE[271] := 0;
        RETURN;
      END_IF;
    ELSE(*未回零，随意上升*)
      IF g_fSenFeng_SupCylType1=0.0 THEN
        g_noSupCentringSwitch1 := 30;
      ELSE
        g_noSupCentringSwitch1 := 10;
      END_IF;
      g_boSenFeng_SupUpDone1 := FALSE;
      g_boSenFeng_SupDownDone1 := FALSE; 
    END_IF;
  ELSE
    IF g_fSenFeng_SupCylType1=0.0 THEN
      g_noSupCentringSwitch1 := 30;
    ELSE
      g_noSupCentringSwitch1 := 10;
    END_IF;
    g_boSenFeng_SupUpDone1 := FALSE;
    g_boSenFeng_SupDownDone1 := FALSE; 
  END_IF;
  g_nDownCmdCount1 := 0;

END_IF;

IF R_SFSupportDown1.Q THEN
  IF g_fSenFeng_SupCylType1=0.0 THEN
    g_noSupCentringSwitch1 := 80;
  ELSE
    g_noSupCentringSwitch1 := 60;
  END_IF;
  g_bSenFeng_SupDown1 := FALSE;
  g_boSenFeng_SupUpDone1 := FALSE;
  g_boSenFeng_SupDownDone1 := FALSE; 
END_IF;

(*自动下降，默认夹中松开再下降*)
(*开启坐标避让，并且回过零，坐标满足下降条件，并且未执行下降命令，则发送下降命令-----避免重复发送下降*)
IF g_fSup2Cy1InYCoor1-g_fCurrentCoordYBuffer < g_fSup2CylDownDis1 AND g_biAxIsYisHome AND g_bSenF_SupportIsAvoid1 THEN
  IF g_nDownCmdCount1=0 THEN(*互锁，自动下降命令只发一次，知道收到一个上升命令，才会再次检测是否发出下降命令*)
	IF g_boSupCyl2Up1 AND NOT g_boSupCyl2Down1 THEN
		g_bSenFeng_SupDown1 := TRUE;
		g_fSenFeng_SupCylType1 := 1.0;
	END_IF;
    g_nDownCmdCount1 := 1;
  END_IF;

END_IF;  

CASE g_noSupCentringSwitch1 OF 
  0:
    g_noSupCentringSwitch1 := 0;
  10:(*张开对中气缸*)
      g_bCentringCyl2Down1 := TRUE;
      g_noSupCentringSwitch1 := 20;
  20:
    IF g_boCentringCyl2Down_Done1 OR g_bSenFeng_SupCentringNoWait1 THEN(*张开和上升同时*)
      g_noSupCentringSwitch1 := 30;
    END_IF;
  30:(*支撑气缸上升*)
    g_bSupCyl2Up1 := TRUE;
    g_noSupCentringSwitch1 := 40;
  40:
    IF g_boSupCyl2Up_Done1 THEN
      g_noSupCentringSwitch1 := 0;
      g_boSenFeng_SupUpDone1 := TRUE;
      M.ENABLE[271] := 0;
    END_IF;


  60:(*张开对中气缸*)
      g_bCentringCyl2Down1 := TRUE;
      g_noSupCentringSwitch1 := 70;
  70:
    IF g_boCentringCyl2Down_Done1 OR g_bSenFeng_SupCentringNoWait1 THEN(*张开和下降同时*)
      g_noSupCentringSwitch1 := 80;
    END_IF;
  80:(*支撑气缸下降*)
    g_bSupCyl2Down1 := TRUE;
    g_noSupCentringSwitch1 := 90;
  90:
    IF g_boSupCyl2Down_Done1 THEN
      g_noSupCentringSwitch1 := 0;
      g_boSenFeng_SupDownDone1 := TRUE;
      M.ENABLE[271] := 0;
    END_IF;

END_CASE;


